/// The status, body and rate-limit headers of a response, read once.
fn read_response(
    mut response: ureq::http::Response<ureq::Body>,
) -> Result<HttpResponse, String> {
    let number = |name: &str| {
        response
            .headers()
            .get(name)
            .and_then(|value| value.to_str().ok())
